<script setup>import { computed } from 'vue'; import { useRoute } from 'vue-router'; import { Play, Star, Trophy, Palette, PencilLine, BookOpen } from 'lucide-vue-next'; import { games, programs } from '../../data/content'; const route=useRoute(); const section=computed(()=>route.meta.section); const icon=computed(()=>({Learn:BookOpen,Games:Play,Practice:PencilLine,Create:Palette,Achievements:Trophy}[section.value])); const items=computed(()=>section.value==='Learn'?programs:games)</script>
<template><div class="child-explore"><header><div><span class="speech">{{section==='Achievements'?'Look how far you’ve come!':'Choose your next adventure'}}</span><h1>{{section}}</h1><p v-if="section!=='Achievements'">Tap any card to begin. You can’t choose a wrong one!</p></div><component :is="icon"/></header><div v-if="section==='Achievements'" class="badges-showcase"><article v-for="(badge,index) in ['First Lesson','Letter Explorer','Number Star','Five-Day Streak','Shape Finder','Super Learner']" :key="badge" :class="{locked:index>3}"><span>{{['★','A','5','☀','△','♛'][index]}}</span><h3>{{badge}}</h3><p>{{index>3?'Keep learning to unlock':'Unlocked!'}}</p></article></div><div v-else class="explore-grid"><RouterLink v-for="item in items" :key="item.slug" :to="section==='Learn'?`/courses/${item.slug}`:`/play/tunde/activity/${item.slug}`" :class="item.color"><div class="explore-art"><img v-if="item.image" :src="item.image" :alt="item.title"><span v-else>{{item.icon}}</span></div><small>{{item.subject||item.category}}</small><h2>{{item.title}}</h2><p>{{item.description||item.instruction}}</p><b><Play fill="currentColor"/> {{section==='Learn'?'Explore':'Play'}}</b></RouterLink></div></div></template>
